create or replace function public.ssr_resolve_cube(p_anchor_tile_id text,p_z_index integer) returns public.spatial_cubes language plpgsql set search_path to 'pg_catalog','public','extensions' as $$ declare v_anchor public.anchor_tiles%rowtype; v_layer ecology.ssr_vertical_11001_layers%rowtype; v_surface text; v_address text; v_repr text; v_uid text; v_cube public.spatial_cubes%rowtype; begin select * into v_layer from ecology.ssr_vertical_11001_layers where z_index=p_z_index; if not found then raise exception 'SSR Z index outside canonical 11,001-layer registry: %',p_z_index; end if; select * into v_anchor from public.anchor_tiles where anchor_tile_id=p_anchor_tile_id and status='active'; if not found then raise exception 'Unknown, inactive, or unverified SSR AnchorTile: %',p_anchor_tile_id; end if; v_surface:=lower(v_anchor.w3w_address); if left(v_surface,3)<>'///' then v_surface:='///'||ltrim(v_surface,'/'); end if; v_address:=v_surface||'@Z'||case when p_z_index>=0 then '+' else '-' end||lpad(abs(p_z_index)::text,4,'0'); v_uid:=encode(extensions.digest(convert_to(v_address,'UTF8'),'sha256'::text),'hex'); v_repr:='SSR|v2|'||v_address||'|CRS='||v_anchor.surface_crs||'|VD='||coalesce(v_anchor.vertical_datum,'EGM96')||'|ALT_M='||v_layer.altitude_m||'|VERTICAL_REGISTRY=11001'; insert into public.spatial_cubes(cube_uid,anchor_tile_id,canonical_address,z_index,macro_layer,vertical_datum,canonical_representation,metadata) values(v_uid,v_anchor.anchor_tile_id,v_address,p_z_index,v_layer.relative_position,coalesce(v_anchor.vertical_datum,'EGM96'),v_repr,jsonb_build_object('altitude_m',v_layer.altitude_m,'increment_m',v_layer.increment_m,'vertical_registry','ecology.ssr_vertical_11001_layers','layer_count',11001,'uid_rule','SHA256(canonical_address)','anchor_authority_signature',v_anchor.authority_signature,'anchor_metadata_hash',v_anchor.metadata_hash)) on conflict(cube_uid) do update set anchor_tile_id=excluded.anchor_tile_id,canonical_address=excluded.canonical_address,z_index=excluded.z_index,macro_layer=excluded.macro_layer,vertical_datum=excluded.vertical_datum,canonical_representation=excluded.canonical_representation,metadata=excluded.metadata,updated_at=now() returning * into v_cube; return v_cube; end $$;
create or replace function sourcecubes.resolve_candidate_cube(p_anchor_candidate_id uuid,p_z_index integer) returns sourcecubes.cube_bindings language plpgsql set search_path='pg_catalog','sourcecubes','ecology','extensions' as $$ declare v_anchor ecology.ssr_anchor_candidate_registry%rowtype; v_layer ecology.ssr_vertical_11001_layers%rowtype; v_surface text; v_address text; v_uid text; v_binding sourcecubes.cube_bindings%rowtype; begin select * into v_anchor from ecology.ssr_anchor_candidate_registry where id=p_anchor_candidate_id; if not found then raise exception 'Unknown SSR anchor candidate'; end if; if v_anchor.w3w_address is null or v_anchor.latitude is null or v_anchor.longitude is null then raise exception 'Candidate lacks canonical horizontal evidence'; end if; if not exists(select 1 from ecology.ssr_w3w_validation_log l where l.subject_id=p_anchor_candidate_id::text and lower(l.validation_status)='validated') then raise exception 'Candidate lacks validated What3Words evidence'; end if; select * into v_layer from ecology.ssr_vertical_11001_layers where z_index=p_z_index; if not found then raise exception 'Z index outside canonical 11,001-layer registry'; end if; v_surface:=lower(v_anchor.w3w_address); if left(v_surface,3)<>'///' then v_surface:='///'||ltrim(v_surface,'/'); end if; v_address:=v_surface||'@Z'||case when p_z_index>=0 then '+' else '-' end||lpad(abs(p_z_index)::text,4,'0'); v_uid:=encode(extensions.digest(convert_to(v_address,'UTF8'),'sha256'::text),'hex'); insert into sourcecubes.cube_bindings(cube_uid,anchor_candidate_id,z_index,canonical_address,latitude,longitude,altitude_m,macro_layer,vertical_datum,binding_status,evidence_reference,authority_state,canonical_identity_authority) values(v_uid,p_anchor_candidate_id,p_z_index,v_address,v_anchor.latitude,v_anchor.longitude,v_layer.altitude_m,v_layer.relative_position,'EGM96','CANDIDATE_CANONICALIZED_PROMOTION_BLOCKED','Validated W3W candidate + ecology.ssr_vertical_11001_layers','CANDIDATE_CANONICALIZED',false) on conflict(cube_uid) do update set anchor_candidate_id=coalesce(sourcecubes.cube_bindings.anchor_candidate_id,excluded.anchor_candidate_id),canonical_address=excluded.canonical_address,latitude=excluded.latitude,longitude=excluded.longitude,altitude_m=excluded.altitude_m,macro_layer=excluded.macro_layer,vertical_datum=excluded.vertical_datum,binding_status=case when sourcecubes.cube_bindings.canonical_identity_authority then sourcecubes.cube_bindings.binding_status else excluded.binding_status end,evidence_reference=excluded.evidence_reference,updated_at=now() returning * into v_binding; return v_binding; end $$;
create or replace function sourcecubes.resolve_authoritative_cube(p_anchor_tile_id text,p_z_index integer) returns sourcecubes.cube_bindings language plpgsql set search_path='pg_catalog','sourcecubes','public','ecology' as $$ declare v_cube public.spatial_cubes%rowtype; v_anchor public.anchor_tiles%rowtype; v_layer ecology.ssr_vertical_11001_layers%rowtype; v_binding sourcecubes.cube_bindings%rowtype; begin select * into v_cube from public.ssr_resolve_cube(p_anchor_tile_id,p_z_index); select * into v_anchor from public.anchor_tiles where anchor_tile_id=p_anchor_tile_id; select * into v_layer from ecology.ssr_vertical_11001_layers where z_index=p_z_index; insert into sourcecubes.cube_bindings(cube_uid,spatial_cube_id,anchor_tile_id,z_index,canonical_address,latitude,longitude,altitude_m,macro_layer,vertical_datum,binding_status,evidence_reference,authority_state,canonical_identity_authority) values(v_cube.cube_uid,v_cube.id,p_anchor_tile_id,p_z_index,v_cube.canonical_address,v_anchor.latitude,v_anchor.longitude,v_layer.altitude_m,v_layer.relative_position,coalesce(v_anchor.vertical_datum,'EGM96'),'AUTHORITATIVE_ACTIVE','public.spatial_cubes + public.anchor_tiles + ecology.ssr_vertical_11001_layers','SSR_CANONICAL',true) on conflict(cube_uid) do update set spatial_cube_id=excluded.spatial_cube_id,anchor_tile_id=excluded.anchor_tile_id,canonical_address=excluded.canonical_address,latitude=excluded.latitude,longitude=excluded.longitude,altitude_m=excluded.altitude_m,macro_layer=excluded.macro_layer,vertical_datum=excluded.vertical_datum,binding_status='AUTHORITATIVE_ACTIVE',authority_state='SSR_CANONICAL',canonical_identity_authority=true,evidence_reference=excluded.evidence_reference,updated_at=now() returning * into v_binding; return v_binding; end $$;
update sourcecubes.integration_spec set version='2.0',status='IMPLEMENTED_CONTROLLED_CANDIDATE_MODE',canonical_registry='public.spatial_cubes',horizontal_registry='public.anchor_tiles',vertical_registry='ecology.ssr_vertical_11001_layers',namespace_policy='Modern SourceCube identity is SHA-256 of canonical address ///what3words@Z±NNNN. Horizontal authority is public.anchor_tiles; vertical authority is ecology.ssr_vertical_11001_layers (-4000..7000, 11,001 layers). public.spatial_cubes is the canonical cube registry. sourcecubes.cube_bindings is the integration/control mirror. DCA-729 remains optional governance metadata, not geography. Dynamic AIR/LAND/SEA evidence is attached through sourcecubes.cube_evidence_bindings and never changes canonical identity authority.',updated_at=now() where spec_id='SC-SSR-001';
